create table public.editor_roles (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check (role in ('admin','editor')), created_at timestamptz not null default now());
create table public.profile (id boolean primary key default true check (id), display_name text, short_name text, professional_headline text, professional_email text, linkedin_url text, location text, availability_text text, site_url text, github_username text not null, resume_url text, updated_at timestamptz not null default now());
create table public.experience (id uuid primary key default gen_random_uuid(), role text not null, organization text not null, employment_type text, location text, start_date text, end_date text, summary text, highlights text, technologies text, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.education (id uuid primary key default gen_random_uuid(), institution text not null, degree text, field text, location text, start_date text, end_date text, status text, highlights text, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.project_links (project_key text primary key check (project_key in ('clauseforge','incidentpilot','medscout','network-fraud-detection')), github_url text, live_demo_url text, updated_at timestamptz not null default now());
create table public.project_assets (id uuid primary key default gen_random_uuid(), project_key text not null check (project_key in ('clauseforge','incidentpilot','medscout','network-fraud-detection')), storage_path text not null, public_url text not null, created_at timestamptz not null default now());
alter table public.profile enable row level security; alter table public.experience enable row level security; alter table public.education enable row level security; alter table public.project_links enable row level security; alter table public.project_assets enable row level security;
create policy "public portfolio reads" on public.profile for select using (true); create policy "public experience reads" on public.experience for select using (true); create policy "public education reads" on public.education for select using (true); create policy "public project link reads" on public.project_links for select using (true); create policy "public asset reads" on public.project_assets for select using (true);
create policy "editors manage profile" on public.profile for all using (exists (select 1 from public.editor_roles where user_id = auth.uid())) with check (exists (select 1 from public.editor_roles where user_id = auth.uid()));
create policy "editors manage experience" on public.experience for all using (exists (select 1 from public.editor_roles where user_id = auth.uid())) with check (exists (select 1 from public.editor_roles where user_id = auth.uid()));
create policy "editors manage education" on public.education for all using (exists (select 1 from public.editor_roles where user_id = auth.uid())) with check (exists (select 1 from public.editor_roles where user_id = auth.uid()));
create policy "editors manage project links" on public.project_links for all using (exists (select 1 from public.editor_roles where user_id = auth.uid())) with check (exists (select 1 from public.editor_roles where user_id = auth.uid()));
create policy "editors manage assets" on public.project_assets for all using (exists (select 1 from public.editor_roles where user_id = auth.uid())) with check (exists (select 1 from public.editor_roles where user_id = auth.uid()));
